return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 && n%100<=99 ? 4 : 5);','language'=>'ar','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'قم بتوصيل حسابات WordPress بـ Active Directory أو OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'بيانات المستخدم','Single sign-on'=>'تسجيل الدخول الموحد','Custom user fields'=>'حقول المستخدم المخصصة','Copy LDAP attributes to WordPress user meta fields.'=>'انسخ سمات LDAP إلى حقول بيانات المستخدم في WordPress.','Field mappings'=>'تعيينات الحقول','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'تعيين واحد لكل سطر: سمة LDAP: مفتاح بيانات WordPress: نوع. مثال: %1$s. الأنواع: %2$s أو %3$s.','Custom field storage'=>'تخزين الحقول المخصصة','Leave the defaults unless your integration uses different user meta keys.'=>'اترك الإعدادات الافتراضية ما لم تستخدم تكاملًا بمفاتيح بيانات مستخدم مختلفة.','LDAP value suffix'=>'لاحقة قيمة LDAP','Stores the LDAP value, such as phone_ldap.'=>'يخزن قيمة LDAP، مثل phone_ldap.','WordPress value suffix'=>'لاحقة قيمة WordPress','Stores the editable WordPress value, such as phone_wp.'=>'يخزن القيمة القابلة للتعديل في WordPress، مثل phone_wp.','Single sign-on (SSO)'=>'تسجيل الدخول الموحد (SSO)','Your web server must authenticate users and set REMOTE_USER. Never copy a browser header into REMOTE_USER or allow access that bypasses server authentication. Set the LDAP search account on Connection.'=>'يجب على خادم الويب مصادقة المستخدمين وتعيين REMOTE_USER. لا تنسخ رأس المتصفح إلى REMOTE_USER أو تسمح بالوصول الذي يتجاوز مصادقة الخادم. قم بتعيين حساب البحث LDAP في الاتصال.','Enable automatic login after web server authentication.'=>'تمكين تسجيل الدخول التلقائي بعد مصادقة خادم الويب.','Web server authentication'=>'مصادقة خادم الويب','REMOTE_USER is present.'=>'REMOTE_USER موجود.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER مفقود. تحقق من تكوين خادم الويب.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'تم إيقاف التحديث. قم بتفعيل Simple LDAP Login Pro لاستعادة تسجيل الدخول عبر LDAP.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'تم حظر التحديث: هذه الحزمة لا تتضمن جميع ملفات Pro. لتثبيت النسخة المجانية، قم بإلغاء تنشيط الإضافة أولاً. ستظل الملفات والإعدادات المثبتة كما هي.','WordPress could not reactivate the plugin.'=>'لم يتمكن WordPress من إعادة تنشيط المكون الإضافي.','Simple LDAP Login needs PHP 8.1 or later.'=>'يحتاج Simple LDAP Login إلى PHP 8.1 أو أحدث.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'ملفات المكون الإضافي مفقودة. أعد تثبيت Simple LDAP Login من ملف ZIP الإصدار.','You do not have permission to change these settings.'=>'ليس لديك إذن لتغيير هذه الإعدادات.','The settings scope has changed. Open the settings page and try again.'=>'لقد تغير نطاق الإعدادات. افتح صفحة الإعدادات وحاول مرة أخرى.','You do not have permission to view these settings.'=>'ليس لديك إذن لعرض هذه الإعدادات.','Network settings'=>'إعدادات الشبكة','Site settings'=>'إعدادات الموقع','LDAP login settings'=>'إعدادات تسجيل الدخول عبر LDAP','Connect to LDAP, then test a login before enabling authentication.'=>'اتصل بـ LDAP، ثم اختبر تسجيل الدخول قبل تمكين المصادقة.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'تم تعطيل تسجيل الدخول عبر LDAP و SSO بواسطة SLL_DISABLE_LDAP في wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'تستخدم إعداداتك المحفوظة SSO أو حقول مستخدم مخصصة. قم بتثبيت Simple LDAP Login Pro لاستخدام هذه الميزات. يتم الاحتفاظ بإعداداتك.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'لا يمكن قراءة كلمة مرور البحث LDAP المحفوظة. أدخلها مرة أخرى في علامة التبويب الاتصال.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'PHP LDAP مفقود. اطلب من مضيفك تثبيته قبل تمكين تسجيل الدخول عبر LDAP.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'تُرسل كلمات مرور LDAP بدون تشفير. استخدم StartTLS أو LDAPS إذا كان خادمك يدعمه.','Save settings'=>'حفظ الإعدادات','Settings on other tabs are kept.'=>'تُحفظ الإعدادات في علامات تبويب أخرى.','LDAP connection'=>'اتصال LDAP','LDAP login'=>'تسجيل الدخول عبر LDAP','Enable LDAP authentication.'=>'تمكين مصادقة LDAP.','Directory type'=>'نوع الدليل','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / دليل LDAP آخر','LDAP servers'=>'خوادم LDAP','One hostname or IP address per line. Servers are tried in order.'=>'اسم مضيف أو عنوان IP واحد لكل سطر. يتم تجربة الخوادم بالترتيب.','Base DN'=>'Base DN','Where to search for users. Example: DC=example,DC=org.'=>'أين تبحث عن المستخدمين. مثال: DC=example,DC=org.','Username suffix'=>'لاحقة اسم المستخدم','Added to usernames without a domain. Example: @example.org.'=>'تضاف إلى أسماء المستخدمين بدون نطاق. مثال: @example.org.','Windows domain'=>'نطاق Windows','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'اسم نطاق قصير، مثل EXAMPLE. له أولوية على لاحقة اسم المستخدم.','Connection security'=>'أمان الاتصال','TLS requires a trusted server certificate.'=>'يتطلب TLS شهادة خادم موثوقة.','StartTLS (recommended)'=>'StartTLS (موصى به)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'LDAP غير مشفر','Unencrypted LDAP requires permission on the Advanced tab.'=>'يتطلب LDAP غير المشفر إذنًا في علامة التبويب المتقدمة.','Port'=>'المنفذ','389 for StartTLS; 636 for LDAPS.'=>'389 لـ StartTLS؛ 636 لـ LDAPS.','Search subfolders'=>'البحث في المجلدات الفرعية','Search all organizational units below the Base DN.'=>'البحث في جميع الوحدات التنظيمية أسفل Base DN.','LDAP search account'=>'حساب البحث عبر LDAP','An LDAP account with read access to users and groups.'=>'حساب LDAP له حق الوصول للقراءة إلى المستخدمين والمجموعات.','Search account'=>'حساب البحث','LDAP bind DN or account name.'=>'DN ربط LDAP أو اسم الحساب.','Search account password'=>'كلمة مرور حساب البحث','Leave blank to keep the saved password.'=>'اتركه فارغًا للاحتفاظ بكلمة المرور المحفوظة.','Login rules'=>'قواعد تسجيل الدخول','Require LDAP passwords'=>'تطلب كلمات مرور LDAP','Block WordPress passwords except for recovery access.'=>'حظر كلمات مرور WordPress باستثناء الوصول إلى الاسترداد.','Local recovery access'=>'الوصول المحلي للاسترداد','Selected administrators'=>'المسؤولون المحددون','All super administrators (legacy)'=>'جميع المشرفين الفائقين (القديم)','All administrators (legacy)'=>'جميع المشرفين (القديم)','Off'=>'إيقاف','Choose who can use a WordPress password when LDAP passwords are required.'=>'اختر من يمكنه استخدام كلمة مرور WordPress عندما تكون كلمات مرور LDAP مطلوبة.','Automatic account creation'=>'إنشاء حساب تلقائي','Create a WordPress account on the first successful LDAP login.'=>'إنشاء حساب WordPress عند أول تسجيل دخول ناجح عبر LDAP.','Default role'=>'الدور الافتراضي','For new accounts only.'=>'للحسابات الجديدة فقط.','Required groups'=>'المجموعات المطلوبة','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'اسم مجموعة واحد لكل سطر. يجب أن ينتمي المستخدمون إلى مجموعة واحدة على الأقل. اتركه فارغًا للسماح لجميع مستخدمي LDAP.','Recovery accounts'=>'حسابات الاسترداد','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'للمسؤولين المحددين فقط. استخدم حسابات محلية منفصلة مع كلمات مرور WordPress. اضغط على Ctrl أو Command لتحديد حسابات متعددة.','Connection options'=>'خيارات الاتصال','Change these only if the default values do not work with your directory.'=>'غير هذه فقط إذا كانت القيم الافتراضية لا تعمل مع الدليل الخاص بك.','LDAP timeout (seconds)'=>'مهلة LDAP (ثواني)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'أقصى انتظار لعملية LDAP. الافتراضي: 5 ثوانٍ.','Login attribute'=>'سمة تسجيل الدخول','Attribute used to find users. Default: uid.'=>'السمة المستخدمة للعثور على المستخدمين. الافتراضي: uid.','Allow unencrypted LDAP'=>'السماح بـ LDAP غير مشفر','Allow passwords to be sent without encryption.'=>'السماح بإرسال كلمات المرور بدون تشفير.','Group search'=>'بحث المجموعة','Group base DN'=>'DN قاعدة المجموعة','Leave blank to use the user Base DN.'=>'اتركه فارغًا لاستخدام DN قاعدة المستخدم.','Group name attribute'=>'سمة اسم المجموعة','Default: cn.'=>'افتراضي: cn.','Group member attribute'=>'سمة عضو المجموعة','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'افتراضي: memberUid. استخدم member أو uniqueMember إذا كانت المجموعات تخزن DN المستخدمين.','Profile attributes'=>'سمات الملف الشخصي','LDAP attributes copied to new WordPress accounts.'=>'سمات LDAP المنسوخة إلى حسابات WordPress الجديدة.','First name attribute'=>'سمة الاسم الأول','Last name attribute'=>'سمة الاسم الأخير','Email attribute'=>'سمة البريد الإلكتروني','Website attribute'=>'سمة الموقع الإلكتروني','Data retention'=>'احتفاظ البيانات','Delete settings when removing the plugin'=>'احذف الإعدادات عند إزالة المكون الإضافي','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'احذف الإعدادات المحفوظة وبيانات اعتماد LDAP عند حذف WordPress للمكون الإضافي. احتفظ بحسابات المستخدمين.','Test LDAP login'=>'اختبار تسجيل الدخول LDAP','Save your settings, then run both tests. Keep this administrator session open.'=>'احفظ إعداداتك، ثم قم بتشغيل كلا الاختبارين. احتفظ بجلسة المسؤول هذه مفتوحة.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'تتحقق الاختبارات من الاتصال وكلمة المرور والمجموعات المطلوبة. لا تنشئ حسابات أو تسجل دخول المستخدمين.','After both tests pass, enable LDAP and try logging in from another browser.'=>'بعد اجتياز كلا الاختبارين، قم بتمكين LDAP وحاول تسجيل الدخول من متصفح آخر.','Recovery'=>'استرداد','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'إذا كنت محجوزًا، قم بإعادة تسمية مجلد simple-ldap-login باستخدام مدير ملفات الاستضافة الخاص بك. سجل الدخول باستخدام كلمة مرور مسؤول WordPress، ثم استعد المجلد وصحح الإعدادات.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'بالنسبة لأخطاء الشهادة، اطلب من مضيفك تكوين هيئة الشهادة LDAP الموثوقة.','LDAP tests'=>'اختبارات LDAP','Tests use saved settings.'=>'تستخدم الاختبارات الإعدادات المحفوظة.','1. Test connection'=>'1. اختبار الاتصال','Connect to LDAP and test the search account, if set.'=>'الاتصال بـ LDAP واختبار حساب البحث، إذا تم تعيينه.','Test connection'=>'اختبار الاتصال','2. Test login'=>'2. اختبار تسجيل الدخول','Check an LDAP username, password, and group membership.'=>'تحقق من اسم مستخدم LDAP وكلمة المرور وعضوية المجموعة.','LDAP username'=>'اسم مستخدم LDAP','LDAP password'=>'كلمة مرور LDAP','Settings saved.'=>'تم حفظ الإعدادات.','Connection test passed.'=>'تم اجتياز اختبار الاتصال.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'لا يمكن الاتصال بـ LDAP. تحقق من الخادم، المنفذ، شهادة TLS، وحساب البحث.','LDAP login test passed. No account was created.'=>'تم اجتياز اختبار تسجيل الدخول LDAP. لم يتم إنشاء حساب.','LDAP login test failed. Check the username, password, and required groups.'=>'فشل اختبار تسجيل الدخول LDAP. تحقق من اسم المستخدم وكلمة المرور والمجموعات المطلوبة.','Could not save settings. Check the values and try again.'=>'لم يتمكن من حفظ الإعدادات. تحقق من القيم وحاول مرة أخرى.','Connection'=>'الاتصال','Access'=>'الوصول','Advanced'=>'متقدم','Troubleshooting'=>'استكشاف الأخطاء وإصلاحها','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'تسجيل الدخول LDAP الخاص بك صالح، لكنك بحاجة إلى حساب WordPress. اتصل بمدير موقعك.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'اسم مستخدم LDAP الخاص بك ليس اسم مستخدم WordPress صالح. اتصل بمدير موقعك.','The default WordPress role is not available. Contact your site administrator.'=>'الدور الافتراضي في WordPress غير متاح. اتصل بمدير موقعك.','Could not create your WordPress account. Contact your site administrator.'=>'لم يتمكن من إنشاء حساب WordPress الخاص بك. اتصل بمدير موقعك.','Use your WordPress password for this recovery account.'=>'استخدم كلمة مرور WordPress الخاصة بك لهذا الحساب الاستردادي.','LDAP login failed. Check your username and password or contact your site administrator.'=>'فشل تسجيل الدخول LDAP. تحقق من اسم المستخدم وكلمة المرور الخاصة بك أو اتصل بمدير موقعك.','Your account is not allowed to log in to this site.'=>'حسابك غير مسموح له بتسجيل الدخول إلى هذا الموقع.','LDAP login is unavailable. Contact your site administrator.'=>'تسجيل الدخول عبر LDAP غير متاح. اتصل بمدير الموقع الخاص بك.','PHP OpenSSL is required to save the LDAP search password.'=>'يتطلب PHP OpenSSL لحفظ كلمة مرور بحث LDAP.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'لم يتمكن من قراءة أو حفظ كلمة مرور بحث LDAP. أدخلها مرة أخرى. إذا استمر هذا، اطلب من مضيفك التحقق من OpenSSL ومفتاح التشفير.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'اختر حساب استرداد في علامة التبويب الوصول، أو قم بإيقاف تشغيل الوصول المحلي للاسترداد.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'قم بتمكين السماح بـ LDAP غير المشفر في علامة التبويب المتقدمة، أو اختر StartTLS أو LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'يستخدم تعيين الحقول المخصصة مفتاح بيانات مستخدم WordPress محمي أو غير صالح.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'أدخل DN أساسي و LDAP خادم واحد على الأقل قبل تمكين تسجيل الدخول عبر LDAP.','WordPress could not save the settings. Try again.'=>'لم يتمكن WordPress من حفظ الإعدادات. حاول مرة أخرى.','LDAP protocol version'=>'إصدار بروتوكول LDAP','LDAP timeout'=>'مهلة LDAP','Check the submitted settings. No changes were saved.'=>'تحقق من الإعدادات المقدمة. لم يتم حفظ أي تغييرات.','Check %s. No changes were saved.'=>'تحقق من %s. لم يتم حفظ أي تغييرات.']];